import { apiClient } from "@/lib/apiClient";

// Tur detayı — apiv3 native budanmış uç (yalnız sitenin kullandığı alanlar döner).
// Eski tam-payload'lı /apiv2/b2c/tours/detail/{slug} ucu apiv3'te duruyor; B2B
// partnerler onu kullanmaya devam ediyor.
export default async function getTourDetail(slug: string) {
    return apiClient(`/tours/detail?slug=${encodeURIComponent(slug)}`, {
        cache: "force-cache",
    });
}
